package zellijinstall

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const testBinary = "/opt/bin/cogitator"

// userShapedConfig mirrors the structure of a tmux-style zellij config:
// clear-defaults keybinds, locked default mode, Ctrl a into normal.
const userShapedConfig = `//
// THIS FILE WAS AUTOGENERATED BY ZELLIJ
//

keybinds clear-defaults=true {
    locked {
        bind "Ctrl a" { SwitchToMode "normal"; }
    }
    // tmux-style prefix table: Ctrl a, then one key, then back to locked
    normal {
        bind "c" { NewTab; SwitchToMode "locked"; }
        bind "s" {
            LaunchOrFocusPlugin "session-manager" {
                floating true
                move_to_focused_tab true
            }
            SwitchToMode "locked"
        }
    }
    shared_among "normal" "locked" {
        bind "Ctrl h" { MoveFocus "left"; }
    }
    /* a { block } comment */
    renamepane {
        bind "esc" { UndoRenamePane; SwitchToMode "pane"; }
    }
}

// Plugin aliases - can be used to change the implementation of Zellij
plugins {
    tab-bar location="zellij:tab-bar"
}
theme "tokyo-night-storm"
default_mode "locked"
`

type testEnv struct {
	home      string
	conf      string
	installer Installer
	out       *bytes.Buffer
}

func newTestEnv(t *testing.T) testEnv {
	t.Helper()

	home := t.TempDir()
	out := &bytes.Buffer{}

	return testEnv{
		home: home,
		conf: filepath.Join(home, ".config", "zellij", "config.kdl"),
		out:  out,
		installer: Installer{
			Home:       home,
			LookPath:   func(string) (string, error) { return "", errors.New("not on PATH") },
			Executable: func() (string, error) { return testBinary, nil },
			Out:        out,
		},
	}
}

func writeFile(t *testing.T, path, content string, mode os.FileMode) {
	t.Helper()

	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), mode); err != nil {
		t.Fatal(err)
	}
}

func readFile(t *testing.T, path string) string {
	t.Helper()

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}

	return string(data)
}

func TestInstallInsertsBlockInsideFirstKeybindsNode(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	content := readFile(t, env.conf)
	if got := strings.Count(content, beginMarker); got != 1 {
		t.Fatalf("want 1 owned block, got %d in:\n%s", got, content)
	}

	opening := "keybinds clear-defaults=true {\n    " + beginMarker
	if !strings.Contains(content, opening) {
		t.Fatalf("block not right after the keybinds opening line:\n%s", content)
	}
	if strings.Count(content, "keybinds ") != 1 {
		t.Fatalf("a second keybinds node was added:\n%s", content)
	}

	wantNext := `        bind "Space" { Run "/opt/bin/cogitator" "next" { floating true; close_on_exit true; }; SwitchToMode "locked"; }`
	wantPick := `        bind "a" { Run "/opt/bin/cogitator" "pick" { floating true; close_on_exit true; width "70%"; height "60%"; x "15%"; y "20%"; }; SwitchToMode "locked"; }`
	for _, want := range []string{`    shared_among "normal" {`, wantNext, wantPick, "    " + endMarker + "\n    locked {"} {
		if !strings.Contains(content, want) {
			t.Fatalf("missing %q in:\n%s", want, content)
		}
	}
}

func TestInstallTwiceKeepsSingleBlock(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}
	first := readFile(t, env.conf)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}
	if got := readFile(t, env.conf); got != first {
		t.Fatalf("second install changed the file:\n%s", got)
	}
	if !strings.Contains(env.out.String(), "already has the cogitator keybinds") {
		t.Fatalf("unexpected output: %q", env.out.String())
	}

	if err := env.installer.Install(Options{PickKey: "A"}); err != nil {
		t.Fatal(err)
	}
	content := readFile(t, env.conf)
	if got := strings.Count(content, beginMarker); got != 1 {
		t.Fatalf("re-install with new keys: want 1 block, got %d", got)
	}
	if strings.Contains(content, `bind "a"`) || !strings.Contains(content, `bind "A"`) {
		t.Fatalf("re-install did not replace the block:\n%s", content)
	}
}

func TestUninstallRestoresOriginalBytes(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o600)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}
	if err := env.installer.Uninstall(Options{}); err != nil {
		t.Fatal(err)
	}

	if got := readFile(t, env.conf); got != userShapedConfig {
		t.Fatalf("uninstall did not restore the original:\n%s", got)
	}

	info, err := os.Stat(env.conf)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode().Perm() != 0o600 {
		t.Fatalf("mode not preserved: %v", info.Mode().Perm())
	}
}

func TestUninstallWithoutBlockLeavesFileAlone(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Uninstall(Options{}); err != nil {
		t.Fatal(err)
	}

	if got := readFile(t, env.conf); got != userShapedConfig {
		t.Fatalf("file changed:\n%s", got)
	}
	if !strings.Contains(env.out.String(), "no cogitator keybinds") {
		t.Fatalf("unexpected output: %q", env.out.String())
	}
}

func TestInstallBindsCustomKeys(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{NextKey: "n", PickKey: "A"}); err != nil {
		t.Fatal(err)
	}

	content := readFile(t, env.conf)
	if !strings.Contains(content, `bind "n" { Run "/opt/bin/cogitator" "next"`) {
		t.Fatalf("next key not bound:\n%s", content)
	}
	if !strings.Contains(content, `bind "A" { Run "/opt/bin/cogitator" "pick"`) {
		t.Fatalf("pick key not bound:\n%s", content)
	}
}

func TestInstallRejectsInvalidKey(t *testing.T) {
	env := newTestEnv(t)

	if err := env.installer.Install(Options{NextKey: `a" { Quit; }`}); err == nil {
		t.Fatal("expected invalid key to be rejected")
	}
}

func TestInstallDryRunWritesNothing(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{DryRun: true}); err != nil {
		t.Fatal(err)
	}

	if got := readFile(t, env.conf); got != userShapedConfig {
		t.Fatalf("dry run wrote the config:\n%s", got)
	}
	if !strings.Contains(env.out.String(), "would write to ") || !strings.Contains(env.out.String(), beginMarker) {
		t.Fatalf("dry run did not print the block: %q", env.out.String())
	}
}

func TestUninstallDryRunWritesNothing(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)
	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}
	installed := readFile(t, env.conf)

	if err := env.installer.Uninstall(Options{DryRun: true}); err != nil {
		t.Fatal(err)
	}

	if got := readFile(t, env.conf); got != installed {
		t.Fatal("uninstall dry run changed the config")
	}
}

func TestInstallFollowsSymlinkedConfig(t *testing.T) {
	env := newTestEnv(t)
	target := filepath.Join(env.home, "dotfiles", "zellij.kdl")
	writeFile(t, target, userShapedConfig, 0o600)
	if err := os.MkdirAll(filepath.Dir(env.conf), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, env.conf); err != nil {
		t.Fatal(err)
	}

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	info, err := os.Lstat(env.conf)
	if err != nil {
		t.Fatal(err)
	}
	if info.Mode()&os.ModeSymlink == 0 {
		t.Fatal("config.kdl is no longer a symlink")
	}
	if !strings.Contains(readFile(t, target), beginMarker) {
		t.Fatal("symlink target not updated")
	}

	targetInfo, err := os.Stat(target)
	if err != nil {
		t.Fatal(err)
	}
	if targetInfo.Mode().Perm() != 0o600 {
		t.Fatalf("mode not preserved: %v", targetInfo.Mode().Perm())
	}
}

func TestInstallAppendsKeybindsNodeWhenNoneExists(t *testing.T) {
	env := newTestEnv(t)
	original := "theme \"dracula\"\n// keybinds { commented out }\n"
	writeFile(t, env.conf, original, 0o644)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	content := readFile(t, env.conf)
	if !strings.HasPrefix(content, original+beginLine+"\nkeybinds {\n    shared_among \"tmux\" {\n") {
		t.Fatalf("keybinds node not appended in tmux mode:\n%s", content)
	}
	if strings.Contains(content, `SwitchToMode "locked"`) || !strings.Contains(content, `close_on_exit true; }; SwitchToMode "normal"; }`) {
		t.Fatalf("tmux-mode binds must return to normal:\n%s", content)
	}
	if !strings.HasSuffix(content, "    }\n}\n"+endMarker+"\n") {
		t.Fatalf("appended node not closed:\n%s", content)
	}
	if !strings.Contains(env.out.String(), "mode: tmux → returns to normal") {
		t.Fatalf("output does not name the mode: %q", env.out.String())
	}

	if err := env.installer.Uninstall(Options{}); err != nil {
		t.Fatal(err)
	}
	if got := readFile(t, env.conf); got != original {
		t.Fatalf("uninstall did not restore the original:\n%s", got)
	}
}

func TestInstallUsesNormalModeForLockedDefault(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	content := readFile(t, env.conf)
	if !strings.Contains(content, `    shared_among "normal" {`) || strings.Contains(content, `shared_among "tmux"`) || strings.Contains(content, `}; SwitchToMode "normal"; }`) {
		t.Fatalf("locked-default config should get the normal-mode block:\n%s", content)
	}
	if !strings.Contains(env.out.String(), "mode: normal → returns to locked") {
		t.Fatalf("output does not name the mode: %q", env.out.String())
	}
}

func TestInstallUsesTmuxModeUnlessDefaultIsLocked(t *testing.T) {
	cases := map[string]string{
		"no default_mode":       "keybinds {\n    normal {\n    }\n}\n",
		"default_mode normal":   "default_mode \"normal\"\nkeybinds {\n}\n",
		"locked only commented": "// default_mode \"locked\"\n/* default_mode \"locked\" */\nkeybinds {\n}\n",
		"locked only nested":    "plugins {\n    default_mode \"locked\"\n}\nkeybinds {\n}\n",
		"last one wins":         "default_mode \"locked\"\ndefault_mode \"normal\"\nkeybinds {\n}\n",
	}

	for name, original := range cases {
		t.Run(name, func(t *testing.T) {
			env := newTestEnv(t)
			writeFile(t, env.conf, original, 0o644)

			if err := env.installer.Install(Options{}); err != nil {
				t.Fatal(err)
			}

			content := readFile(t, env.conf)
			if !strings.Contains(content, "keybinds {\n    "+beginMarker) || !strings.Contains(content, `shared_among "tmux" {`) {
				t.Fatalf("want tmux-mode block inside keybinds:\n%s", content)
			}
			if strings.Contains(content, `SwitchToMode "locked"`) {
				t.Fatalf("tmux-mode binds must return to normal:\n%s", content)
			}
		})
	}
}

func TestInstallCreatesConfigWhenMissing(t *testing.T) {
	env := newTestEnv(t)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	if !strings.HasPrefix(readFile(t, env.conf), beginLine+"\nkeybinds {\n") {
		t.Fatal("config not created with a keybinds node")
	}
}

func TestInstallSkipsNestedKeybindsWords(t *testing.T) {
	env := newTestEnv(t)
	original := "plugins {\n    keybinds location=\"x\" {\n    }\n}\nkeybinds {\n    locked {\n    }\n}\n"
	writeFile(t, env.conf, original, 0o644)

	if err := env.installer.Install(Options{}); err != nil {
		t.Fatal(err)
	}

	content := readFile(t, env.conf)
	if !strings.Contains(content, "}\nkeybinds {\n    "+beginMarker) {
		t.Fatalf("block not inserted in the top-level keybinds node:\n%s", content)
	}
}

func TestInstallRejectsSingleLineKeybindsNode(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, "keybinds { normal { bind \"x\" { Quit; } } }\n", 0o644)

	if err := env.installer.Install(Options{}); err == nil {
		t.Fatal("expected an error for a keybinds node it cannot extend")
	}
}

func TestInstallQuotesBinaryPathForKDL(t *testing.T) {
	env := newTestEnv(t)
	writeFile(t, env.conf, userShapedConfig, 0o644)

	if err := env.installer.Install(Options{Binary: `/opt/my "odd"\dir/cogitator`}); err != nil {
		t.Fatal(err)
	}

	if !strings.Contains(readFile(t, env.conf), `Run "/opt/my \"odd\"\\dir/cogitator" "next"`) {
		t.Fatalf("binary not KDL-quoted:\n%s", readFile(t, env.conf))
	}
}

func TestInstallRejectsGoRunBinary(t *testing.T) {
	env := newTestEnv(t)

	if err := env.installer.Install(Options{Binary: "/var/tmp/go-build123/b001/exe/cogitator"}); err == nil {
		t.Fatal("expected go run binary to be rejected")
	}
}

func TestConfigLookupOrder(t *testing.T) {
	home := "/home/u"
	cases := []struct {
		name      string
		installer Installer
		explicit  string
		want      string
	}{
		{"flag wins", Installer{Home: home, ConfigFile: "/f.kdl", ConfigDir: "/d"}, "/x.kdl", "/x.kdl"},
		{"ZELLIJ_CONFIG_FILE", Installer{Home: home, ConfigFile: "/f.kdl", ConfigDir: "/d"}, "", "/f.kdl"},
		{"ZELLIJ_CONFIG_DIR", Installer{Home: home, ConfigDir: "/d"}, "", "/d/config.kdl"},
		{"home default", Installer{Home: home}, "", "/home/u/.config/zellij/config.kdl"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := tc.installer.configPath(tc.explicit); got != tc.want {
				t.Fatalf("configPath = %q, want %q", got, tc.want)
			}
		})
	}
}
